# compile: longest-first, word boundaries, case-insensitive. Entries with a trailing space mean "token followed by space" (go, r).
def _pat(term):
    t = term.strip(); esc = re.escape(t)
    if term.endswith(' '): return r"(?<![\w+#.])" + esc + r"(?![\w+#])"
    return r"(?<![\w+#.])" + esc + r"(?![\w+#])"
TERM2FAM = {}
for fam, terms in LEX.items():
    for t in terms: TERM2FAM.setdefault(t.strip().lower(), fam)
ALL_TERMS = sorted(TERM2FAM.keys(), key=len, reverse=True)
RE_SKILLS = re.compile("|".join(_pat(t) for t in ALL_TERMS), re.I)
# ambiguous single tokens kept only when the posting is tech/AI scoped (handled by caller): 'go', 'r', 'bi', 'ux', 'ui', 'api', 'dash', 'sas', 'poc', 'safe', 'lora', 'claude', 'mistral', 'diffusion', 'tokens', 'prompt', 'drift', 'glue', 'lambda', 'vertex', 'support', 'maintenance', 'audit', 'responsable', 'sécurité', 'security', 'commerce', 'customer', 'conseil', 'recherche', 'research', 'innovation', 'management', 'organisation', 'organization', 'communication', 'stress', 'deadline'
AMBIGUOUS = {'go', 'r', 'bi', 'ux', 'ui', 'dash', 'sas', 'poc', 'safe', 'lora', 'claude', 'mistral', 'diffusion', 'tokens', 'prompt', 'drift', 'glue', 'lambda', 'vertex', 'inference', 'transformer', 'responsable', 'gemini', 'ros', 'gpu', 'classification', 'segmentation', 'scoring', 'mcp', 'bert', 'yolo', 'chroma', 'spring', 'node', 'rest', 'vue', 'react', 'go ',
             # over-generic words removed from the dictionary (they match boilerplate rather than a skill)
             'environnement', 'environment', 'recherche', 'research', 'organisation', 'organization', 'support', 'conseil', 'sécurité', 'security', 'innovation', 'recrutement', 'recruiting', 'pilotage', 'management', 'commerce', 'customer', 'maintenance', 'stress', 'deadline', 'délais', 'mobilité', 'déplacements', 'formation', 'adoption', 'budget', 'planning', 'coordination', 'initiative', 'transport', 'énergie', 'energy', 'santé', 'health', 'industrie', 'industry', 'finance', 'retail', 'marketing', 'éducation', 'education', 'juridique', 'legal', 'droit', 'normes', 'standards', 'audit', 'risques', 'gouvernance', 'governance', 'conformité', 'compliance', 'transparence', 'transparency', 'communication', 'collaboration', 'autonomie', 'autonomy', 'rigueur', 'créativité', 'creativity', 'leadership', 'écoute', 'listening', 'télétravail', 'remote', 'hybride', 'hybrid', 'permis b', 'anglais', 'english', 'français', 'french', 'automatisation', 'automation', 'optimisation', 'optimization', 'reporting', 'kpi', 'dashboard', 'tableau de bord', 'cloud', 'api', 'mobile', 'web services', 'json', 'xml', 'html', 'css', 'excel', 'analytics', 'data', 'ia', 'ai'}

def extract(text, strict=True):
    if not text: return []
    found = set(m.group(0).lower().strip() for m in RE_SKILLS.finditer(text))
    if strict: found = {t for t in found if t not in AMBIGUOUS}
    return sorted(found)

def family_counts(skills):
    c = {f: 0 for f in FAMILIES}
    for s in skills:
        f = TERM2FAM.get(s)
        if f: c[f] += 1
    return c
